CREATE MATERIALIZED VIEW billing.mv_totals AS
SELECT customer_id,
    sum(amount) AS total
   FROM sales.orders
  GROUP BY customer_id
WITH DATA;
CREATE UNIQUE INDEX mv_totals_customer_idx ON billing.mv_totals USING btree (customer_id);
